export const INTERPOLATION_METHODS={'reference-first':'Reference-curve interpolation','forward-first':'Forward family first, then invert','inverse-distance':'Weighted average (inverse-distance²)'};
function family(c,deps,notes,policy){const independent=c.temperatureIndependent&&['Eon','Eoff'].some(k=>c.xName===k||c.yName===k),keys=[...new Set(c.iterations.flatMap(it=>Object.keys(it.deps||{})))].filter(k=>!independent||k!=='Tj');if(independent&&new Set(c.iterations.map(it=>it.deps?.Tj)).size>1)throw Error('Temperature-independent energy requires a single reference temperature');const axes={};for(const k of keys){if(!Number.isFinite(deps[k])||c.iterations.some(it=>!Number.isFinite(it.deps?.[k])))throw Error('Missing or incomplete operating dependency '+k);axes[k]=[...new Set(c.iterations.map(it=>it.deps[k]))].sort((a,b)=>a-b);if(axes[k].length===1){if(deps[k]!==axes[k][0]&&!(k==='Vds'&&['Eon','Eoff'].some(k=>[c.xName,c.yName].includes(k))))notes.push(`${k} fixed at reference ${axes[k][0]}; requested ${deps[k]}`);}else if(deps[k]<axes[k][0]||deps[k]>axes[k].at(-1)){if(policy==='error')throw Error(`Dependency ${k}=${deps[k]} outside [${axes[k][0]}, ${axes[k].at(-1)}]`);notes.push(`Dependency ${k}=${deps[k]} outside [${axes[k][0]}, ${axes[k].at(-1)}]`);}}return axes;}
const forwardCache=new WeakMap();
export function interpolateCurve(c,input,given,wanted,deps,policy,notes,method,base,lerp){if(!c||c.constant!==undefined||method==='reference-first'||!method)return base(c,input,given,wanted,deps,policy,notes);if(!['forward-first','inverse-distance'].includes(method))throw Error('Unknown interpolation method '+method);if(!c.iterations?.length)throw Error('Characteristic has no iterations');
 if(method==='inverse-distance'){const axes=family(c,deps,notes,policy),varying=Object.keys(axes).filter(k=>axes[k].length>1),target={...deps};if(policy==='clamp')for(const k of varying)target[k]=Math.max(axes[k][0],Math.min(axes[k].at(-1),deps[k]));const distances=c.iterations.map(it=>varying.reduce((s,k)=>s+((it.deps[k]-target[k])/(axes[k].at(-1)-axes[k][0]))**2,0)),exact=distances.some(d=>d<1e-20),weights=distances.map(d=>exact?(d<1e-20?1:0):1/d),total=weights.reduce((a,b)=>a+b,0);let result=0;for(let j=0;j<c.iterations.length;j++)if(weights[j]){const it=c.iterations[j];result+=weights[j]/total*base({...c,iterations:[it]},input,given,wanted,it.deps||{},policy,notes);}notes.push('Weighted average: inverse-distance² on normalised dependency ranges; heuristic model');if(c.temperatureIndependent)notes.push('Switching energy assumed temperature-independent');return result;}
 if(c.xName===given&&c.yName===wanted)return base(c,input,given,wanted,deps,policy,notes);if(c.yName!==given||c.xName!==wanted)throw Error('Characteristic axes do not support this query');
 let cache=forwardCache.get(c);if(!cache){cache=new Map();forwardCache.set(c,cache);}const key=JSON.stringify([deps,policy]);let model=cache.get(key);
 if(!model){const modelNotes=[],axes=family(c,deps,modelNotes,policy);let refs=c.iterations;
 // Ignore reference slices with zero weight at an exact dependency boundary.
 for(const [k,values] of Object.entries(axes)){if(values.length>1&&values.includes(deps[k]))refs=refs.filter(it=>it.deps[k]===deps[k]);}
 const curve={...c,iterations:refs},ranges=refs.map(it=>[Math.min(...it.x),Math.max(...it.x)]),strict=['error','clamp'].includes(policy),lo=strict?Math.max(...ranges.map(r=>r[0])):Math.min(...ranges.map(r=>r[0])),hi=strict?Math.min(...ranges.map(r=>r[1])):Math.max(...ranges.map(r=>r[1]));if(!(hi>lo))throw Error('Forward-family curves have no common usable X interval');const x=[...new Set([lo,hi,...refs.flatMap(it=>it.x).filter(v=>v>=lo&&v<=hi)])].sort((a,b)=>a-b),y=x.map(v=>base(curve,v,c.xName,c.yName,deps,policy,modelNotes));const delta=y.slice(1).map((v,j)=>v-y[j]),tol=1e-12*Math.max(1,...y.map(Math.abs));if(delta.some(v=>v>tol)&&delta.some(v=>v<-tol))throw Error('Interpolated forward family is nonmonotonic; select a single physical branch');if(delta.some(v=>Math.abs(v)<=tol))throw Error('Interpolated forward family contains a flat segment; inversion is ambiguous');model={x,y,notes:[...new Set(modelNotes)]};if(cache.size>256)cache.clear();cache.set(key,model);}
 notes.push(...model.notes,'Forward-family interpolation: dependencies interpolated before inversion');return lerp(model.y,model.x,input,policy==='matlab'?'extrapolate':policy,notes);
}
